"""Lymphoma (ASU Feature Selection Repository) loading + generic preprocessing helpers.

C1 config (paper Section 4.3): 96 instances, 4026 discrete features, 9 classes,
NO standardisation because the covariates are discrete (R13).
"""
from __future__ import annotations

import io
import os
import zipfile
from typing import Tuple

import numpy as np
import scipy.io as sio

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
DATA_DIR = os.path.join(ROOT, "data")

CACHE = os.environ.get("REPRO_DATA_CACHE", "")

# Candidate locations for the raw ASU file, most local first.
_LOCAL_NAMES = ["lymphoma.mat", os.path.join("raw", "lymphoma.mat"),
                os.path.join("asu_lymphoma", "lymphoma.mat")]

_URLS = [
    "https://featureselection.asu.edu/datasets/Lymphoma.zip",
    "https://featureselection.asu.edu/datasets/Lymphoma.mat",
    "http://featureselection.asu.edu/asu_fast/Lymphoma.zip",
    "https://jwcarlson.github.io/data/lymphoma.mat",
]

EXPECTED = dict(n=96, d=4026, classes=9)


def _cache_candidates():
    out = []
    if CACHE:
        for name in ["lymphoma.mat", os.path.join("asu_lymphoma", "lymphoma.mat"),
                     os.path.join("data", "lymphoma.mat")]:
            out.append(os.path.join(CACHE, name))
    return out


def _paths():
    for name in _LOCAL_NAMES:
        yield os.path.join(DATA_DIR, name)
    for p in _cache_candidates():
        yield p


def _parse_mat(path: str) -> Tuple[np.ndarray, np.ndarray]:
    m = sio.loadmat(path)
    keys = {k.lower(): k for k in m.keys() if not k.startswith("__")}
    if "x" not in keys or "y" not in keys:
        raise ValueError(f"unexpected .mat keys: {sorted(m.keys())}")
    X = np.asarray(m[keys["x"]], dtype=np.float64)
    y = np.asarray(m[keys["y"]]).ravel()
    # ASU stores labels as strings sometimes
    if y.dtype.kind in "USO":
        y = np.array([int(str(v).strip()) for v in y])
    y = np.asarray(y, dtype=np.int64)
    if X.shape[0] != y.shape[0] and X.shape[1] == y.shape[0]:
        X = X.T
    return X, y


def _parse_csv(path: str) -> Tuple[np.ndarray, np.ndarray]:
    arr = np.loadtxt(path, delimiter=",")
    if arr.shape[1] < 2:
        arr = np.loadtxt(path)
    X = np.asarray(arr[:, :-1], dtype=np.float64)
    y = np.asarray(arr[:, -1], dtype=np.float64)
    y = np.rint(y).astype(np.int64)
    return X, y


def _try_download(url: str):
    import requests

    r = requests.get(url, timeout=60, verify=False)
    if r.status_code != 200 or len(r.content) < 1000:
        return None
    return r.content


def _materialise(blob: bytes, dest: str) -> str:
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    if blob[:2] == b"PK":  # zip archive
        with zipfile.ZipFile(io.BytesIO(blob)) as zf:
            names = [n for n in zf.namelist() if n.lower().endswith((".mat", ".csv", ".data"))]
            if not names:
                raise RuntimeError("zip has no parsable data file")
            inner = zf.read(names[0])
            with open(dest, "wb") as fh:
                fh.write(inner)
            return dest
    with open(dest, "wb") as fh:
        fh.write(blob)
    return dest


def load_lymphoma(verbose: bool = True) -> Tuple[np.ndarray, np.ndarray]:
    """Return (X, y) for the ASU Lymphoma dataset, un-standardised."""
    for p in _paths():
        if not p or not os.path.exists(p):
            continue
        try:
            X, y = _parse_mat(p) if p.endswith(".mat") else _parse_csv(p)
        except Exception as exc:  # pragma: no cover - defensive
            if verbose:
                print(f"[data] skip {p}: {exc}")
            continue
        if verbose:
            print(f"[data] loaded Lymphoma from {p}")
        return _validate(X, y, verbose)

    os.makedirs(DATA_DIR, exist_ok=True)
    dest = os.path.join(DATA_DIR, "raw", "lymphoma.mat")
    for url in _URLS:
        try:
            blob = _try_download(url)
        except Exception as exc:  # pragma: no cover - network
