"""Cluster-number selection: agglomerative clustering of the learned centroids + SSE elbow.

Implements Section 2.6 (R10, R11).
"""
from __future__ import annotations

from typing import Dict, List

import numpy as np
from scipy.cluster.hierarchy import fcluster, linkage
from scipy.spatial.distance import pdist


def labels_from_centroids(C: np.ndarray, k: int, linkage_method: str = "average") -> np.ndarray:
    """R10: agglomerative clustering on the learned centroids, cut into k clusters."""
    if C.shape[0] <= 1:
        return np.zeros(C.shape[0], dtype=int)
    k = int(max(1, min(k, C.shape[0])))
    Zl = linkage(pdist(np.asarray(C, dtype=float)), method=linkage_method)
    lab = fcluster(Zl, t=k, criterion="maxclust")
    # relabel to 0..k-1
    u = np.unique(lab)
    remap = {v: i for i, v in enumerate(u)}
    return np.array([remap[v] for v in lab], dtype=int)


def sse_curve(C: np.ndarray, kmax: int, linkage_method: str = "average") -> Dict[int, float]:
    """SSE_k = sum over clusters of the within-cluster squared distances to the cluster mean."""
    C = np.asarray(C, dtype=float)
    n = C.shape[0]
    kmax = int(min(max(2, kmax), n))
    Zl = linkage(pdist(C), method=linkage_method)
    out: Dict[int, float] = {}
    for k in range(2, kmax + 1):
        lab = fcluster(Zl, t=k, criterion="maxclust")
        sse = 0.0
        for c in np.unique(lab):
            pts = C[lab == c]
            sse += float(np.sum((pts - pts.mean(axis=0)) ** 2))
        out[k] = sse
    return out


def elbow_from_sse(sse: Dict[int, float]) -> int:
    """R11 / A8: Kneedle elbow of SSE_k vs k = argmax of the (normalised) distance to the chord."""
    ks = np.array(sorted(sse.keys()), dtype=float)
    ys = np.array([sse[int(k)] for k in ks], dtype=float)
    if len(ks) < 3:
        return int(ks[0])
    x = (ks - ks[0]) / (ks[-1] - ks[0])
    lo, hi = ys.min(), ys.max()
    if hi - lo <= 0:
        return int(ks[0])
    y = (ys - lo) / (hi - lo)
    # distance to the line joining the first and last normalised points
    d = (1.0 - x) * y - ((1.0 - x) * y[0] + x * y[-1] - y) * 0.0  # keep explicit below
    line = y[0] + x * (y[-1] - y[0])
    diff = y - line          # SSE decreases: the elbow is where the curve is furthest BELOW... 
    # For a decreasing convex curve the elbow (knee) is the point of maximum distance to the chord.
    dist = np.abs(line - y)
    j = int(np.argmax(dist))
    return int(ks[j])


def cluster_diagnostics(C: np.ndarray, kmax: int = 12,
                        linkage_method: str = "average") -> Dict[str, object]:
    sse = sse_curve(C, kmax, linkage_method)
    eb = elbow_from_sse(sse)
    return {"sse": sse, "elbow_k": eb,
            "labels": {k: labels_from_centroids(C, k, linkage_method) for k in sse}}


def silhouette(X: np.ndarray, labels: np.ndarray) -> float:
    """Label-free internal validity index (used for hyper-parameter selection)."""
    from sklearn.metrics import silhouette_score
    u = np.unique(labels)
    if len(u) < 2 or len(u) == X.shape[0]:
        return -1.0
    try:
        return float(silhouette_score(X, labels))
    except Exception:
        return -1.0

